from scipy.signal import iirfilter
import numpy as np

def run():
    try:
        b, a = iirfilter(20, [1000000000, 1100000000], btype='bp', analog=False, fs=6250000000)
        b = np.asarray(b, dtype=float)
        a = np.asarray(a, dtype=float)
        return {
            'ok': True,
            'b0_3': b[:3].tolist(),
            'a0_3': a[:3].tolist(),
            'b_sum_abs': float(np.sum(np.abs(b))),
            'a_sum_abs': float(np.sum(np.abs(a))),
        }
    except Exception as e:
        return {
            'ok': False,
            'exc_type': type(e).__name__,
            'exc_msg': str(e)[:500]
        }

result = run()
probe(result)

